+function parseItem(item: string): PortRange {
+  const trimmed = item.trim();
+  if (trimmed === "") {
+    throw new Error("empty item");
+  }
+  const parts = trimmed.split("-");
+  if (parts.length > 2) {
+    throw new Error("invalid item");
+  }
+  if (parts.length === 1) {
+    const n = Number(parts[0]);
+    if (!/^\d+$/.test(parts[0]) || n < 1 || n > 65535) {
+      throw new Error("invalid port");
+    }
+    return [n, n];
+  }
+  const fromStr = parts[0].trim();
+  const toStr = parts[1].trim();
+  if (fromStr === "" || toStr === "") {
+    throw new Error("invalid range");
+  }
+  const from = Number(fromStr);
+  const to = Number(toStr);
+  if (!/^\d+$/.test(fromStr) || !/^\d+$/.test(toStr) || from < 1 || from > 65535 || to < 1 || to > 65535) {
+    throw new Error("invalid port");
+  }
+  if (to < from) {
+    throw new Error("range end below start");
+  }
+  return [from, to];
+}

